ALTER TABLE resale_settings ADD COLUMN title_style TEXT NOT NULL DEFAULT 'professional', ADD COLUMN title_max_length INTEGER NOT NULL DEFAULT 40, ADD COLUMN excluded_keywords TEXT[] NOT NULL DEFAULT '{}', ADD COLUMN required_keywords TEXT[] NOT NULL DEFAULT '{}';
ALTER TABLE resale_settings ADD COLUMN auto_metrics BOOLEAN NOT NULL DEFAULT false;
ALTER TABLE resale_listings ADD COLUMN metrics_checked_at TIMESTAMPTZ, ADD COLUMN metrics_error TEXT;
ALTER TABLE resale_listings ADD COLUMN title_candidates TEXT[] NOT NULL DEFAULT '{}', ADD COLUMN content_keywords TEXT[] NOT NULL DEFAULT '{}', ADD COLUMN content_warnings TEXT[] NOT NULL DEFAULT '{}', ADD COLUMN publish_at TIMESTAMPTZ;
CREATE TABLE resale_monitors (id TEXT PRIMARY KEY, keyword TEXT NOT NULL, min_price_cny DOUBLE PRECISION NOT NULL DEFAULT 0, max_price_cny DOUBLE PRECISION NOT NULL DEFAULT 1000000, excluded_keywords TEXT[] NOT NULL DEFAULT '{}', required_keywords TEXT[] NOT NULL DEFAULT '{}', regions TEXT[] NOT NULL DEFAULT '{}', interval_minutes INTEGER NOT NULL DEFAULT 60, active BOOLEAN NOT NULL DEFAULT false, last_scan_at TIMESTAMPTZ, next_scan_at TIMESTAMPTZ, lease_token TEXT, lease_until TIMESTAMPTZ, last_error TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX resale_monitors_active_next_scan_at_idx ON resale_monitors(active, next_scan_at);
CREATE TABLE resale_market_observations (id TEXT PRIMARY KEY, monitor_id TEXT NOT NULL REFERENCES resale_monitors(id), target_item_id TEXT NOT NULL, title TEXT NOT NULL, price_cny DOUBLE PRECISION NOT NULL, region TEXT NOT NULL DEFAULT '', source_url TEXT NOT NULL, image_url TEXT, discovered_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, last_seen_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, read_at TIMESTAMPTZ);
CREATE UNIQUE INDEX resale_market_observations_monitor_id_target_item_id_key ON resale_market_observations(monitor_id,target_item_id);
CREATE INDEX resale_market_observations_discovered_at_idx ON resale_market_observations(discovered_at);
CREATE TABLE resale_metric_snapshots (id TEXT PRIMARY KEY, listing_id TEXT NOT NULL REFERENCES resale_listings(id), views INTEGER, wants INTEGER, orders INTEGER, revenue_cny DOUBLE PRECISION, origin TEXT NOT NULL DEFAULT 'manual', observed_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
ALTER TABLE resale_metric_snapshots ADD COLUMN target_item_id TEXT NOT NULL;
CREATE UNIQUE INDEX resale_metric_snapshots_listing_id_observed_at_key ON resale_metric_snapshots(listing_id,observed_at);
CREATE TABLE resale_seller_tasks (id TEXT PRIMARY KEY, listing_id TEXT NOT NULL REFERENCES resale_listings(id), listing_version INTEGER NOT NULL, target_item_id TEXT NOT NULL, kind TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'queued', price_cny DOUBLE PRECISION, scheduled_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, started_at TIMESTAMPTZ, finished_at TIMESTAMPTZ, account_id TEXT NOT NULL, last_error TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX resale_seller_tasks_status_scheduled_at_idx ON resale_seller_tasks(status,scheduled_at);
CREATE INDEX resale_seller_tasks_listing_id_kind_created_at_idx ON resale_seller_tasks(listing_id,kind,created_at);
